package com.ekayn.api.api;
import com.ekayn.api.api.ApiModels.*; import com.ekayn.api.model.*; import com.ekayn.api.repo.OrderRepository; import com.ekayn.api.service.EmailNotVerifiedException; import com.ekayn.api.service.OrderService; import com.stripe.Stripe; import com.stripe.model.checkout.Session; import com.stripe.net.RequestOptions; import com.stripe.param.checkout.SessionCreateParams; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/checkout") @RequiredArgsConstructor
public class CheckoutController {
  private final OrderService orders; private final OrderRepository orderRepository; @Value("${stripe.api-key:}") String stripeKey; @Value("${app.frontend-url}") String frontend;
  @PostMapping("/quote") public ShippingQuoteResponse quote(@AuthenticationPrincipal User user,@Valid @RequestBody OrderInput input){return orders.quote(user,input);}
  @PostMapping("/session") public CheckoutSessionResponse session(@AuthenticationPrincipal User user,@RequestHeader(value="Idempotency-Key",required=true) String key,@Valid @RequestBody OrderInput input){
    if(!user.isEmailVerified()) throw new EmailNotVerifiedException(); if(key.isBlank()||key.length()>100) throw new IllegalArgumentException("Clé d’idempotence invalide.");
    var existing=orderRepository.findByUserIdAndCheckoutIdempotencyKey(user.getId(),key); if(existing.isPresent()){var o=existing.get();if(o.getStripeCheckoutUrl()!=null)return response(o.getStripeCheckoutUrl(),o);throw new IllegalArgumentException("Cette tentative de paiement doit être relancée avec une nouvelle clé.");}
    if(stripeKey.isBlank())throw new IllegalArgumentException("Stripe n’est pas configuré."); Stripe.apiKey=stripeKey; Order order=orders.create(user,input,key);
    try {var builder=SessionCreateParams.builder().setMode(SessionCreateParams.Mode.PAYMENT).setCustomerEmail(user.getEmail()).setSuccessUrl(frontend+"/checkout/success?session_id={CHECKOUT_SESSION_ID}").setCancelUrl(frontend+"/checkout/cancel").putMetadata("order_id",order.getId().toString()).setClientReferenceId(order.getId().toString());
      for(var item:order.getItems()){var price=SessionCreateParams.LineItem.PriceData.builder().setCurrency("eur").setUnitAmount(item.getUnitPrice().movePointRight(2).longValueExact()).setProductData(SessionCreateParams.LineItem.PriceData.ProductData.builder().setName(item.getProductName()).build()).build();builder.addLineItem(SessionCreateParams.LineItem.builder().setQuantity((long)item.getQuantity()).setPriceData(price).build());}
      if(order.getShippingCost().compareTo(java.math.BigDecimal.ZERO)>0){var price=SessionCreateParams.LineItem.PriceData.builder().setCurrency("eur").setUnitAmount(order.getShippingCost().movePointRight(2).longValueExact()).setProductData(SessionCreateParams.LineItem.PriceData.ProductData.builder().setName(order.getShippingMethodLabel()).build()).build();builder.addLineItem(SessionCreateParams.LineItem.builder().setQuantity(1L).setPriceData(price).build());}
      Session session=Session.create(builder.build(),RequestOptions.builder().setIdempotencyKey(key).build()); order.setStripeCheckoutSessionId(session.getId()); order.setStripeCheckoutUrl(session.getUrl()); order.setStripePaymentIntentId(session.getPaymentIntent()); return response(session.getUrl(),orders.save(order));
    } catch(Exception e){order.setPaymentStatus(Enums.PaymentStatus.CHECKOUT_FAILED);orders.save(order);throw new IllegalArgumentException("Impossible de préparer le paiement.");}
  }
  private CheckoutSessionResponse response(String url,Order o){return new CheckoutSessionResponse(url);}
}
